$json$::jsonb;
  e record;
  n int;
  uid text;
  urole text;
  v_email text;
  v_rows int;
BEGIN
  FOR e IN SELECT * FROM jsonb_to_recordset(v_data) AS x(ordre int, prenom text, nom text, ligne text) ORDER BY ordre LOOP
    SELECT count(*), min(id), min(role) INTO n, uid, urole
    FROM users
    WHERE regexp_replace(translate(lower(btrim(prenom || ' ' || nom)), 'àâäáãéèêëíìîïóòôöõúùûüçñ', 'aaaaaeeeeiiiiooooouuuucn'), '\s+', ' ', 'g') IN (regexp_replace(translate(lower(btrim(e.prenom || ' ' || e.nom)), 'àâäáãéèêëíìîïóòôöõúùûüçñ', 'aaaaaeeeeiiiiooooouuuucn'), '\s+', ' ', 'g'), regexp_replace(translate(lower(btrim(e.nom || ' ' || e.prenom)), 'àâäáãéèêëíìîïóòôöõúùûüçñ', 'aaaaaeeeeiiiiooooouuuucn'), '\s+', ' ', 'g'));

    IF n = 1 AND urole = 'CONSEILLER' THEN
      UPDATE users SET "phoneNumber" = e.ligne, prenom = e.prenom, nom = e.nom
      WHERE id = uid AND ("phoneNumber" IS DISTINCT FROM e.ligne OR prenom IS DISTINCT FROM e.prenom OR nom IS DISTINCT FROM e.nom);
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      IF v_rows > 0 THEN RAISE NOTICE '% % : mis à jour (ligne %)', e.prenom, e.nom, e.ligne; END IF;
    ELSIF n = 1 THEN
      RAISE NOTICE '% % : ignoré, cet utilisateur a le rôle %', e.prenom, e.nom, urole;
    ELSIF n > 1 THEN
      RAISE NOTICE '% % : ignoré, % utilisateurs portent ce nom', e.prenom, e.nom, n;
    ELSIF v_creer_manquants THEN
      v_email := regexp_replace(regexp_replace(translate(lower(btrim(e.prenom || '.' || e.nom)), 'àâäáãéèêëíìîïóòôöõúùûüçñ', 'aaaaaeeeeiiiiooooouuuucn'), '[^a-z0-9]+', '.', 'g'), '(^\.+|\.+$)', '', 'g') || '@assurpilot.fr';
      INSERT INTO users (id, email, password, nom, prenom, "phoneNumber", role, "isActive")
      VALUES ('c' || substr(md5(random()::text || clock_timestamp()::text || e.ordre::text), 1, 24), v_email,
              '!inutilisable!' || md5(random()::text || clock_timestamp()::text), e.nom, e.prenom, e.ligne, 'CONSEILLER', true)
      ON CONFLICT (email) DO NOTHING;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      IF v_rows > 0 THEN RAISE NOTICE '% % : créé (%)', e.prenom, e.nom, v_email;
      ELSE RAISE NOTICE '% % : NON créé, l''e-mail % existe déjà', e.prenom, e.nom, v_email; END IF;
    END IF;
  END LOOP;
END $$;

-- Result: one row per conseiller of the list (single line on purpose: some SQL editors cut
-- multi-line statements). statut = OK when the user exists with exactly this prénom, nom and
-- line; anything else needs a look (see the comments above).
SELECT e.ordre, e.prenom, e.nom, e.ligne, CASE WHEN u.id IS NULL THEN 'ABSENT (non trouvé / non créé / ambigu)' WHEN u.role <> 'CONSEILLER' THEN 'IGNORÉ : rôle ' || u.role WHEN u.prenom = e.prenom AND u.nom = e.nom AND u."phoneNumber" = e.ligne THEN 'OK' ELSE 'À VÉRIFIER' END AS statut, u.email, u."isActive" AS actif, t.nom AS equipe, (SELECT count(*) FROM users s WHERE s."phoneNumber" = e.ligne) AS utilisateurs_sur_cette_ligne FROM jsonb_to_recordset($json$[{"ordre":1,"prenom":"Hicham","nom":"","ligne":"0374470362"},{"ordre":2,"prenom":"Sonia","nom":"AMARI","ligne":"0374470949"},{"ordre":3,"prenom":"Eva","nom":"ARENA","ligne":"0374474002"},{"ordre":4,"prenom":"Laurie","nom":"Blanchard","ligne":"0980805173"},{"ordre":5,"prenom":"Sylla","nom":"CASTEL","ligne":"0162536014"},{"ordre":6,"prenom":"Brahim","nom":"CHOUHRA","ligne":"0374471625"},{"ordre":7,"prenom":"Ines","nom":"CLARET","ligne":"0255995583"},{"ordre":8,"prenom":"Sabrina","nom":"COHEN","ligne":"0187667156"},{"ordre":9,"prenom":"Matheo","nom":"DEBRUNI","ligne":"0988288361"},{"ordre":10,"prenom":"Mickael","nom":"DELATTRE","ligne":"0374474285"},{"ordre":11,"prenom":"Sébastien","nom":"DUQUENNE","ligne":"0374471541"},{"ordre":12,"prenom":"Theo","nom":"GARCIA","ligne":"0180873470"},{"ordre":13,"prenom":"Nicolas","nom":"GOMEZ","ligne":"0189707489"},{"ordre":14,"prenom":"Emmanuel","nom":"JAMES","ligne":"0162534692"},{"ordre":15,"prenom":"SARAH","nom":"LAURENT","ligne":"0374470495"},{"ordre":16,"prenom":"Eric","nom":"Lawson","ligne":"0980804573"},{"ordre":17,"prenom":"Sophie","nom":"LEROY","ligne":"0189707561"},{"ordre":18,"prenom":"Benjamin","nom":"LOMBARDI","ligne":"0988995223"},{"ordre":19,"prenom":"Jonas","nom":"MAURY","ligne":"0374471351"},{"ordre":20,"prenom":"Joseph","nom":"MULLER","ligne":"0184808789"},{"ordre":21,"prenom":"Yanis","nom":"OSMAN","ligne":"0189706317"},{"ordre":22,"prenom":"Aurélie","nom":"PASQUIER","ligne":"0189703668"},{"ordre":23,"prenom":"Katia","nom":"PLAZA","ligne":"0970703911"},{"ordre":24,"prenom":"Sabrina","nom":"romano","ligne":"0374471057"},{"ordre":25,"prenom":"Pierre","nom":"SIMON","ligne":"0189703772"},{"ordre":26,"prenom":"ANTOINE","nom":"ROSSI","ligne":"0755540595"},{"ordre":27,"prenom":"YOHAN","nom":"RODI","ligne":"0755522944"},{"ordre":28,"prenom":"RAPHAEL","nom":"ARNAULT","ligne":"0755540595"},{"ordre":29,"prenom":"Sarah","nom":"FALION","ligne":"0374474976"},{"ordre":30,"prenom":"Julien","nom":"COHEN","ligne":"0189706056"},{"ordre":31,"prenom":"Clara","nom":"Thomas","ligne":"0189701897"},{"ordre":32,"prenom":"JULIA","nom":"CAULIER","ligne":"0980804137"},{"ordre":33,"prenom":"Raphael","nom":"Dubrin","ligne":"0970703794"},{"ordre":34,"prenom":"Karine","nom":"Gomez","ligne":"0374474976"},{"ordre":35,"prenom":"Samia","nom":"Alaoui","ligne":"0187669043"},{"ordre":36,"prenom":"Nael","nom":"GIRO","ligne":"0745898106"},{"ordre":37,"prenom":"Yohan","nom":"Bertrand","ligne":"0189706926"},{"ordre":38,"prenom":"Antoine","nom":"Babin","ligne":"0189707796"},{"ordre":39,"prenom":"Jason","nom":"FONTENEAU","ligne":"0187660690"},{"ordre":40,"prenom":"Didier","nom":"ARAFAT","ligne":"0187662096"},{"ordre":41,"prenom":"Sonia","nom":"Lammar","ligne":"0162535323"},{"ordre":42,"prenom":"Ramzi","nom":"Daquin","ligne":"0162538127"},{"ordre":43,"prenom":"César","nom":"Perez","ligne":"0189706039"},{"ordre":44,"prenom":"Mario","nom":"Barazzi","ligne":"0189703742"}]$json$::jsonb) AS e(ordre int, prenom text, nom text, ligne text) LEFT JOIN users u ON regexp_replace(translate(lower(btrim(u.prenom || ' ' || u.nom)), 'àâäáãéèêëíìîïóòôöõúùûüçñ', 'aaaaaeeeeiiiiooooouuuucn'), '\s+', ' ', 'g') IN (regexp_replace(translate(lower(btrim(e.prenom || ' ' || e.nom)), 'àâäáãéèêëíìîïóòôöõúùûüçñ', 'aaaaaeeeeiiiiooooouuuucn'), '\s+', ' ', 'g'), regexp_replace(translate(lower(btrim(e.nom || ' ' || e.prenom)), 'àâäáãéèêëíìîïóòôöõúùûüçñ', 'aaaaaeeeeiiiiooooouuuucn'), '\s+', ' ', 'g')) LEFT JOIN teams t ON t.id = u."teamId" ORDER BY e.ordre;
